/* Returns 1 if otmp is free'd, 0 otherwise. */
/**
 * @param {$T.monst | null} mtmp struct monst *
 * @param {$T.obj | null} otmp struct obj *
 * @returns {Promise<number>} int
 */
export async function mpickobj(mtmp, otmp) {   // steal.c:618
    let snuff_otmp = FALSE;
    if (!otmp) {
        await impossible($C`monster (%s) taking or picking up nothing?`,
            pmname(mtmp.data, Mgender(mtmp)));
        return 1;
    } else if (otmp === $G.uball || otmp === $G.uchain) {
        await impossible($C`monster (%s) taking or picking up attached %s (%s)?`,
            pmname(mtmp.data, Mgender(mtmp)),
            otmp === $G.uchain ? $C`chain` : $C`ball`, await simpleonames(otmp));
        return 0;
    }
    /* if monster is acquiring a thrown or kicked object, the throwing
       or kicking code shouldn't continue to track and place it */
    if (otmp === gt.thrownobj) {
        gt.thrownobj = null;
    } else if (otmp === gk.kickedobj) {
        gk.kickedobj = null;
    }
    /* an unpaid item can be on the floor; if a monster picks it up, take
       it off the shop bill */
    if (otmp.unpaid || Has_contents(otmp) && count_unpaid(otmp.cobj)) {
        await subfrombill(otmp, await find_objowner(otmp, otmp.ox, otmp.oy));
    }
    /* don't want hidden light source inside the monster; assumes that
       engulfers won't have external inventories; whirly monsters cause
       the light to be extinguished rather than letting it shine through */
    if (obj_sheds_light(otmp) && attacktype(mtmp.data, AT.ENGL)) {
        /* this is probably a burning object that you dropped or threw */
        if (engulfing_u(mtmp) && !Blind()) {
            await pline($C`%s out.`, await Tobjnam(otmp, $C`go`));
        }
        snuff_otmp = TRUE;
    }
    /* for hero owned object on shop floor, mtmp is taking possession
       and if it's eventually dropped in a shop, shk will claim it */
    otmp.no_charge = 0;
    /* some object handling is only done if mtmp isn't a pet */
    if (!mtmp.mtame) {
        /* if monst is unseen, some info hero knows about this object becomes
           lost; continual pickup and drop by pets makes this too annoying if
           it is applied to them; when engulfed (where monster can't be seen
           because vision is disabled), or when held (or poly'd and holding)
           while blind, behave as if the monster can be 'seen' by touch */
        if (!canseemon(mtmp) && mtmp !== u.ustuck) {
            unknow_object(otmp);
        }
        /* if otmp has flags set for how it left hero's inventory, change
           those flags; if thrown, now stolen and autopickup might override
           pickup_types and autopickup exceptions based on 'pickup_stolen'
           rather than 'pickup_thrown'; if previously stolen, stays stolen;
           if previously dropped, now forgotten and autopickup will operate
           normally regardless of the setting for 'dropped_nopick' */
        if (otmp.how_lost === LOST.THROWN) {
            otmp.how_lost = (LOST.STOLEN) & 7;
        } else if (otmp.how_lost === LOST.DROPPED) {
            otmp.how_lost = (LOST.NONE) & 7;
        }
    }
    /* Must do carrying effects on object prior to add_to_minv() */
    await carry_obj_effects(otmp);
    /* add_to_minv() might free otmp [if merged with something else],
       so we have to call it after doing the object checks */
    const freed_otmp = await add_to_minv(mtmp, otmp);
    /* and we had to defer this until object is in mtmp's inventory */
    if (snuff_otmp) {
        await snuff_light_source(mtmp.mx, mtmp.my);
    }
    return freed_otmp;
}
/* called for AD_SAMU (the Wizard and quest nemeses) */
/**
 * @param {$T.monst | null} mtmp struct monst *
 * @returns {Promise<void>}
 */
export async function stealamulet(mtmp) {   // steal.c:689
    let buf = new Int8Array(256), n = 0;
    let otmp = null;
    let obj = null;
    let real = 0;
    let fake = 0;
    /* target every quest artifact, not just current role's;
       if hero has more than one, choose randomly so that player
       can't use inventory ordering to influence the theft */
    for (n = 0, obj = gi.invent; obj; obj = obj.nobj) {
        if (any_quest_artifact(obj)) {
            n = n + 1 | 0, otmp = obj;
        }
    }
    if (n > 1) {
        n = rnd(n);
        for (otmp = gi.invent; otmp; otmp = otmp.nobj) {
            if (any_quest_artifact(otmp) && !(n = n - 1 | 0)) {
                break;
            }
        }
    }
    if (!otmp) {
        /* if we didn't find any quest artifact, find another valuable item */
        if (u.uhave.amulet) {
            real = AMULET_OF_YENDOR;
            fake = FAKE_AMULET_OF_YENDOR;
        } else if (u.uhave.bell) {
            real = BELL_OF_OPENING;
            fake = BELL;
        } else if (u.uhave.book) {
            real = SPE_BOOK_OF_THE_DEAD;
        } else if (u.uhave.menorah) {
            real = CANDELABRUM_OF_INVOCATION;
        } else {
            return;   /* you have nothing of special interest */
        }
        /* If we get here, real and fake have been set up. */
        for (n = 0, obj = gi.invent; obj; obj = obj.nobj) {
            if (obj.otyp === real || obj.otyp === fake && !mtmp.iswiz) {
                n = n + 1 | 0, otmp = obj;
            }
        }
        if (n > 1) {
            n = rnd(n);
            for (otmp = gi.invent; otmp; otmp = otmp.nobj) {
                if ((otmp.otyp === real
                    || otmp.otyp === fake && !mtmp.iswiz) && !(n = n - 1 | 0)) {
                    break;
                }
            }
        }
    }
    if (otmp) {
        /* we have something to snatch */
        /* take off outer gear if we're targeting [hypothetical]
           quest artifact suit, shirt, gloves, or rings */
        if ((otmp === $G.uarm || otmp === $G.uarmu) && $G.uarmc) {
            await worn_item_removal(mtmp, $G.uarmc);
        }
        if (otmp === $G.uarmu && $G.uarm) {
            await worn_item_removal(mtmp, $G.uarm);
        }
        if ((otmp === $G.uarmg || (otmp === $G.uright || otmp === $G.uleft) && $G.uarmg)
            && $G.uwep) {
            /* gloves are about to be unworn; unwield weapon(s) first */
            if (u.twoweap) {   /* remove_worn_item(uswapwep) indirectly */
                await worn_item_removal(mtmp, $G.uswapwep);   /* clears u.twoweap */
            }
            await worn_item_removal(mtmp, $G.uwep);
        }
        if ((otmp === $G.uright || otmp === $G.uleft) && $G.uarmg) {   /* calls Gloves_off() to handle wielded cockatrice corpse */
            await worn_item_removal(mtmp, $G.uarmg);
        }
        /* finally, steal the target item */
        if (otmp.owornmask) {
            await worn_item_removal(mtmp, otmp);
        }
        if (otmp.unpaid) {
            await subfrombill(otmp, await shop_keeper(new $c.Ptr(u.ushops, 0).get(0)));
        }
        await freeinv(otmp);
        $c.strcpy(new $c.Ptr(buf, 0), await doname(otmp));
        await mpickobj(mtmp, otmp);   /* could merge and free otmp but won't */
        await pline($C`%s steals %s!`, await Some_Monnam(mtmp), new $c.Ptr(buf, 0));
        if (can_teleport(mtmp.data) && !await tele_restrict(mtmp)) {
            await rloc(mtmp, RLOC.MSG);
        }
        await encumber_msg();
    }
}
/* when a mimic gets poked with something, it might take that thing
   (at present, only implemented for when the hero does the poking) */
/**
 * @param {$T.monst | null} mon struct monst *
 * @param {$T.obj | null} obj struct obj *
 * @param {number} ochance int
 * @param {number} achance int
 * @returns {Promise<void>}
 */
export async function maybe_absorb_item(mon, obj, ochance, achance) {   // steal.c:772
    /* percent chance for ordinary item, artifact */
    if (obj === $G.uball || obj === $G.uchain || obj.oclass === ROCK_CLASS
        || obj_resists(obj, 100 - ochance | 0, 100 - achance | 0)
        || !await touch_artifact(obj, mon)) {
        return;
    }
    if (carried(obj)) {
        if (obj.owornmask) {
            await remove_worn_item(obj, TRUE);
        }
        if (obj.unpaid) {
            await subfrombill(obj, await shop_keeper(new $c.Ptr(u.ushops, 0).get(0)));
        }
        if (cansee(mon.mx, mon.my)) {
            /* Some_Monnam() avoids "It pulls ... and absorbs it!"
               if hero can see the location but not the monster */
            /* Monnam() or "Something" */
            await pline($C`%s pulls %s away from you and absorbs %s!`,
                await Some_Monnam(mon),
                await yname(obj), obj.quan > 1 ? $C`them` : $C`it`);
        } else {
            let hand_s = await body_part(HAND);
            if (bimanual(obj)) {
                hand_s = await makeplural(hand_s);
            }
            await pline($C`%s %s pulled from your %s!`, upstart(await yname(obj)),
                await otense(obj, $C`are`), hand_s);
        }
        await freeinv(obj);
        await encumber_msg();
    } else {
        /* not carried; presumably thrown or kicked */
        if (canspotmon(mon)) {
            await pline($C`%s absorbs %s!`, await Monnam(mon), await yname(obj));
        }
    }
    /* add to mon's inventory */
    await mpickobj(mon, obj);
}
/* drop one object taken from a (possibly dead) monster's inventory */
/**
 * @param {$T.monst | null} mon struct monst *
 * @param {$T.obj | null} obj struct obj *
 * @param {number} verbosely boolean
 * @returns {Promise<void>}
 */
export async function mdrop_obj(mon, obj, verbosely) {   // steal.c:814
    const omx = mon.mx;
    const omy = mon.my;
    const unwornmask = obj.owornmask;
    /* call distant_name() for its possible side-effects even if the result
       might not be printed, and do it before extracting obj from minvent */
    const obj_name = await distant_name(obj, doname);
    await extract_from_minvent(mon, obj, FALSE, TRUE);
    /* don't charge for an owned saddle on dead steed (provided
        that the hero is within the same shop at the time) */
    /* being at costly_spot guarantees lev->roomno is not 0 */
    if (unwornmask && mon.mtame && $c.and64(unwornmask, W.SADDLE) !== 0
        && !obj.unpaid && await costly_spot(omx, omy)
        && $c.strchr(in_rooms(u.ux, u.uy, SHOPBASE), svl.level.locations[omx][omy].roomno)) {
        obj.no_charge = 1;
    }
    /* obj_no_longer_held(obj); -- done by place_object */
    if (verbosely && cansee(omx, omy)) {
        await pline_mon(mon, $C`%s drops %s.`, await Monnam(mon), obj_name);
    }
    if (!await flooreffects(obj, omx, omy, $C`fall`)) {
        await place_object(obj, omx, omy);
        await stackobj(obj);
    }
    /* do this last, after placing obj on floor; removing steed's saddle
       throws rider, possibly inflicting fatal damage and producing bones; this
       is why we had to call extract_from_minvent() with do_intrinsics=FALSE */
    if (!DEADMONSTER(mon) && unwornmask) {
        await update_mon_extrinsics(mon, obj, FALSE, TRUE);
    }
}
/* some monsters bypass the normal rules for moving between levels or
   even leaving the game entirely; when that happens, prevent them from
   taking the Amulet, invocation items, or quest artifact with them */
/**
 * @param {$T.monst | null} mon struct monst *
 * @returns {Promise<void>}
 */
export async function mdrop_special_objs(mon) {   // steal.c:852
    let obj = null, otmp = null;
    for (obj = mon.minvent; obj; obj = otmp) {
        otmp = obj.nobj;
        /* the Amulet, invocation tools, and Rider corpses resist even when
           artifacts and ordinary objects are given 0% resistance chance;
           current role's quest artifact is rescued too--quest artifacts
           for the other roles are not */
        if (obj_resists(obj, 0, 0) || is_quest_artifact(obj)) {
            if (mon.mx) {
                await mdrop_obj(mon, obj, FALSE);
            } else {
                /* migrating monster not on map */
                await extract_from_minvent(mon, obj, TRUE, TRUE);
                await rloco(obj);
            }
        }
    }
}
/* release the objects the creature is carrying */
/**
 * @param {$T.monst | null} mtmp struct monst *
 * @param {number} show int
 * @param {number} is_pet boolean
 * @returns {Promise<void>}
 */
export async function relobj(mtmp, show, is_pet) {   // steal.c:875
    let otmp = null;
    /* If true, pet should keep wielded/worn items */
    const omx = mtmp.mx;
    const omy = mtmp.my;
    /* vault guard's gold goes away rather than be dropped... */
    if (mtmp.isgd && (otmp = findgold(mtmp.minvent)) !== null) {
        if (canspotmon(mtmp)) {
            await pline($C`%s gold %s.`, s_suffix(await Monnam(mtmp)),
                canseemon(mtmp) ? $C`vanishes` : $C`seems to vanish`);
        }
        await obj_extract_self(otmp);
        await obfree(otmp, null);
    }   /* isgd && has gold */
    while ((otmp = is_pet ? await droppables(mtmp) : mtmp.minvent) !== null) {
        await mdrop_obj(mtmp, otmp, is_pet && flags.verbose ? 1 : 0);
    }
    if (show && cansee(omx, omy)) {
        await newsym($c.i16(omx), $c.i16(omy));
    }
}

export function $init() {
    steal$how.fill(null);
    $c.init(steal$how, [
        $C`steal`,
        $C`snatch`,
        $C`grab`,
        $C`take`
    ]);
}
